import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { AdminPagesPage } from './AdminPagesPage';
import { adminWorkspace } from './adminWorkspace';
import { deferred, json, session, viewer } from './adminFixtures.testSupport';
import type { AdminPage } from './catalogApi';

const revision = `cr_${'a'.repeat(43)}`;

/** A placement's identity belongs to the Page, independently of its reusable reference. */
function placement(overrides: Partial<AdminPage['items'][number]> = {}): AdminPage['items'][number] {
  return { itemId: '222222222222222222222222', itemType: 'carousel', referenceId: 'shared-carousel', order: 0,
    visibility: 'public', name: 'Featured releases', sourceMode: 'manual', referenceStatus: 'ready', ...overrides };
}

/** Creates only allowlisted administrator Page fields for the endpoint stub. */
function page(overrides: Partial<AdminPage> = {}): AdminPage {
  return { slug: 'home', title: 'Home', revision, items: [placement()], ...overrides };
}

/** Uses the real query and account fences while answering only synthetic requests. */
async function mount() {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(['browser-session'], session);
  await act(async () => render(<QueryClientProvider client={client}><MemoryRouter initialEntries={['/admin/pages']}><AdminPagesPage /></MemoryRouter></QueryClientProvider>));
  return client;
}

/** Narrows assertions to one placement rather than the page's navigation or confirmation. */
function row(name = '1 · Featured releases') {
  return within(screen.getByRole('heading', { name }).closest('li')!);
}

beforeEach(() => {
  adminWorkspace.reset();
  adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true });
  adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

test('only the selected Page is read and counted, and switching does not invent the other count', async () => {
  const reads: string[] = [], pending = deferred<Response>();
  vi.stubGlobal('fetch', vi.fn(async (path: string) => {
    reads.push(path);
    return path.endsWith('/library') ? pending.promise : json({ page: page() });
  }));
  await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  const home = () => screen.getByRole('button', { name: 'Home' });
  const library = () => screen.getByRole('button', { name: 'Library' });
  expect(within(home()).getByText('1')).toBeVisible();
  expect(within(library()).getByText('—')).toBeVisible();
  expect(reads).toEqual(['/api/admin/v1/pages/home']);
  fireEvent.click(library());
  await waitFor(() => expect(reads).toEqual(['/api/admin/v1/pages/home', '/api/admin/v1/pages/library']));
  expect(within(home()).getByText('—')).toBeVisible();
  expect(within(library()).getByText('—')).toBeVisible();
  await act(async () => pending.resolve(json({ page: page({ slug: 'library', title: 'Library', items: [
    placement({ name: 'Recently played' }),
    placement({ itemId: '333333333333333333333333', name: 'Recently saved', order: 1 })
  ] }) })));
  await screen.findByRole('heading', { name: '2 · Recently saved' });
  expect(within(library()).getByText('2')).toBeVisible();
  expect(within(home()).getByText('—')).toBeVisible();
  expect(home()).toHaveAttribute('aria-pressed', 'false');
  expect(library()).toHaveAttribute('aria-pressed', 'true');
});

test('initial loading keeps unknown counts and a disabled refresh without claiming a confirmed empty Page', async () => {
  const pending = deferred<Response>();
  vi.stubGlobal('fetch', vi.fn(() => pending.promise));
  await mount();
  expect(await screen.findByText('Loading…', { exact: true })).toBeVisible();
  expect(screen.getByRole('button', { name: 'Refresh status' })).toBeDisabled();
  expect(screen.queryByText('This page has no placements.')).not.toBeInTheDocument();
  expect(within(screen.getByRole('button', { name: 'Home' })).getByText('—')).toBeVisible();
  await act(async () => pending.resolve(json({ page: page({ items: [] }) })));
  expect(await screen.findByText('This page has no placements.')).toBeVisible();
  expect(within(screen.getByRole('button', { name: 'Home' })).getByText('0')).toBeVisible();
});

test('a failed read uses neutral recovery copy and does not turn the failed count into zero', async () => {
  let failing = true;
  vi.stubGlobal('fetch', vi.fn(async () => failing ? json({ code: 'unavailable' }, 503) : json({ page: page({ items: [] }) })));
  await mount();
  expect(await screen.findByText('Unable to load page items. Try again.')).toBeVisible();
  expect(screen.queryByText('This page has no placements.')).not.toBeInTheDocument();
  expect(within(screen.getByRole('button', { name: 'Home' })).getByText('—')).toBeVisible();
  failing = false;
  fireEvent.click(screen.getByRole('button', { name: 'Try again' }));
  expect(await screen.findByText('This page has no placements.')).toBeVisible();
});

test('refresh retains the confirmed list until the replacement read completes', async () => {
  const pending = deferred<Response>(); let reads = 0;
  vi.stubGlobal('fetch', vi.fn(async () => ++reads === 1 ? json({ page: page() }) : pending.promise));
  await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  const refresh = screen.getByRole('button', { name: 'Refresh status' });
  fireEvent.click(refresh);
  await waitFor(() => expect(refresh).toBeDisabled());
  expect(screen.getByRole('heading', { name: '1 · Featured releases' })).toBeVisible();
  expect(screen.queryByText('This page has no placements.')).not.toBeInTheDocument();
  await act(async () => pending.resolve(json({ page: page({ items: [] }) })));
  expect(await screen.findByText('This page has no placements.')).toBeVisible();
});

test('missing names and sources retain warnings without dangling separators, including in confirmation', async () => {
  vi.stubGlobal('fetch', vi.fn(async () => json({ page: page({ items: [
    placement({ itemType: 'grid', name: null, sourceMode: null, referenceStatus: 'missing' }),
    placement({ itemId: '333333333333333333333333', itemType: 'list', name: 'Legacy list', sourceMode: null, referenceStatus: 'unsupported', visibility: 'hidden', order: 1 })
  ] }) })));
  await mount();
  await screen.findByRole('heading', { name: '1 · Unnamed placement' });
  const unnamed = row('1 · Unnamed placement'), legacy = row('2 · Legacy list');
  expect(unnamed.getByText('Referenced content is missing')).toBeVisible();
  expect(legacy.getByText('Unsupported reference')).toBeVisible();
  expect(unnamed.getByText('Grid', { exact: true })).toBeVisible();
  expect(legacy.getByText('List', { exact: true })).toBeVisible();
  expect(unnamed.queryByText('Manual')).not.toBeInTheDocument();
  expect(unnamed.queryByText('Dynamic')).not.toBeInTheDocument();
  expect(unnamed.getByRole('heading').closest('li')!.textContent).not.toMatch(/Grid\s*·/);
  expect(legacy.getByRole('button', { name: 'Make this placement public' })).toBeEnabled();
  fireEvent.click(unnamed.getByRole('button', { name: 'Hide this placement' }));
  const dialog = within(screen.getByRole('dialog'));
  expect(dialog.getByText('Referenced content is missing')).toBeVisible();
  expect(dialog.getByText('1 · Unnamed placement')).toBeVisible();
  expect(dialog.getByText('Grid', { exact: true })).toBeVisible();
  expect(dialog.queryByText(/Grid\s*·/)).not.toBeInTheDocument();
});

test('reference details are explicit and copying reports success only after the clipboard write resolves', async () => {
  const pending = deferred<void>(), writeText = vi.fn(() => pending.promise);
  vi.stubGlobal('navigator', { ...navigator, clipboard: { writeText } });
  vi.stubGlobal('fetch', vi.fn(async () => json({ page: page() })));
  await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  expect(screen.getByText('shared-carousel')).not.toBeVisible();
  const details = row().getByRole('button', { name: 'Details' });
  fireEvent.click(details);
  expect(row().getByText('shared-carousel')).toBeVisible();
  expect(row().getByRole('button', { name: 'Hide details' })).toHaveAttribute('aria-expanded', 'true');
  fireEvent.click(row().getByRole('button', { name: 'Copy reference ID' }));
  expect(writeText).toHaveBeenCalledExactlyOnceWith('shared-carousel');
  expect(screen.queryByText('Copied', { exact: true })).not.toBeInTheDocument();
  await act(async () => pending.resolve());
  expect(await screen.findByText('Copied', { exact: true })).toBeVisible();
  fireEvent.click(row().getByRole('button', { name: 'Hide details' }));
  expect(screen.getByText('shared-carousel')).not.toBeVisible();
});

test('a rejected clipboard write keeps the selectable reference and offers manual copying', async () => {
  vi.stubGlobal('navigator', { ...navigator, clipboard: { writeText: vi.fn(async () => { throw new DOMException('Denied', 'NotAllowedError'); }) } });
  vi.stubGlobal('fetch', vi.fn(async () => json({ page: page() })));
  await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  fireEvent.click(row().getByRole('button', { name: 'Details' }));
  fireEvent.click(row().getByRole('button', { name: 'Copy reference ID' }));
  expect(await screen.findByText('Could not copy. Select the reference ID and copy it manually.')).toBeVisible();
  expect(screen.getByText('shared-carousel')).toBeVisible();
  expect(screen.queryByText('Copied', { exact: true })).not.toBeInTheDocument();
});

test('a late clipboard result cannot mark a replacement reference as copied', async () => {
  let saved = page(); const pending = deferred<void>();
  const writeText = vi.fn().mockImplementationOnce(() => pending.promise).mockResolvedValue(undefined);
  vi.stubGlobal('navigator', { ...navigator, clipboard: { writeText } });
  vi.stubGlobal('fetch', vi.fn(async () => json({ page: saved })));
  const client = await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  fireEvent.click(row().getByRole('button', { name: 'Details' }));
  fireEvent.click(row().getByRole('button', { name: 'Copy reference ID' }));
  saved = { ...saved, revision: `cr_${'b'.repeat(43)}`, items: [{ ...saved.items[0], referenceId: 'replacement-carousel' }] };
  await act(async () => { await client.refetchQueries({ queryKey: ['admin-imports'] }); });
  expect(await row().findByText('replacement-carousel')).toBeVisible();
  await waitFor(() => expect(row().getByRole('button', { name: 'Copy reference ID' })).toBeEnabled());
  await act(async () => pending.resolve());
  expect(screen.queryByText('Copied', { exact: true })).not.toBeInTheDocument();
  fireEvent.click(row().getByRole('button', { name: 'Copy reference ID' }));
  expect(await screen.findByText('Copied', { exact: true })).toBeVisible();
  expect(writeText.mock.calls).toEqual([['shared-carousel'], ['replacement-carousel']]);
});

test('cancel returns focus to the opener and confirmation returns it to enabled same-row details while the write is pending', async () => {
  const pending = deferred<Response>(); let operationId = '';
  vi.stubGlobal('fetch', vi.fn(async (_path: string, init: RequestInit = {}) => {
    if (init.method !== 'PATCH') return json({ page: page() });
    operationId = JSON.parse(String(init.body)).operationId as string;
    return pending.promise;
  }));
  await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  const opener = row().getByRole('button', { name: 'Hide this placement' });
  opener.focus(); fireEvent.click(opener);
  let dialog = within(screen.getByRole('dialog'));
  await waitFor(() => expect(dialog.getByRole('button', { name: 'Cancel' })).toHaveFocus());
  fireEvent.click(dialog.getByRole('button', { name: 'Cancel' }));
  expect(opener).toHaveFocus();
  fireEvent.click(opener);
  dialog = within(screen.getByRole('dialog'));
  await waitFor(() => expect(dialog.getByRole('button', { name: 'Cancel' })).toHaveFocus());
  fireEvent.click(dialog.getByRole('button', { name: 'Hide this placement' }));
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(opener).toBeDisabled();
  await waitFor(() => expect(row().getByRole('button', { name: 'Details' })).toHaveFocus());
  await act(async () => pending.resolve(json({ page: page({ revision: `cr_${'b'.repeat(43)}`, items: [placement({ visibility: 'hidden' })] }), receipt: { operationId } })));
});

test('a change elsewhere on the Page disables an open approval and explains the Page-level recovery', async () => {
  let saved = page({ items: [placement(), placement({ itemId: '333333333333333333333333', name: 'Other placement', order: 1 })] });
  const writes: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_path: string, init: RequestInit = {}) => {
    if (init.method === 'PATCH') writes.push(String(init.body));
    return json({ page: saved });
  }));
  const client = await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  fireEvent.click(row().getByRole('button', { name: 'Hide this placement' }));
  saved = { ...saved, revision: `cr_${'b'.repeat(43)}`, items: [saved.items[0], { ...saved.items[1], name: 'Changed other placement' }] };
  await act(async () => { await client.refetchQueries({ queryKey: ['admin-imports'] }); });
  const dialog = within(screen.getByRole('dialog'));
  expect(await dialog.findByText('This page has changed. Close this dialog, refresh and review it before confirming again.')).toBeVisible();
  expect(dialog.getByRole('button', { name: 'Hide this placement' })).toBeDisabled();
  expect(dialog.getByRole('button', { name: 'Cancel' })).toBeEnabled();
  expect(writes).toHaveLength(0);
});

test('an unconfirmed hide keeps its captured target across refresh and Page switches, then retries the identical operation', async () => {
  let saved = page(); const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit = {}) => {
    if (path.endsWith('/library')) return json({ page: page({ slug: 'library', title: 'Library', items: [] }) });
    if (init.method !== 'PATCH') return json({ page: saved });
    const body = JSON.parse(String(init.body)) as Record<string, unknown>; writes.push({ path, body });
    if (writes.length === 1) throw new TypeError('Synthetic dropped response');
    saved = { ...saved, revision: `cr_${'c'.repeat(43)}`, items: [{ ...saved.items[0], visibility: 'hidden' }] };
    return json({ page: saved, receipt: { operationId: body.operationId } });
  }));
  const client = await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  fireEvent.click(row().getByRole('button', { name: 'Hide this placement' }));
  fireEvent.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Hide this placement' }));
  await screen.findByRole('button', { name: 'Retry original operation' });
  expect(screen.getByRole('alert')).toHaveTextContent(/1\s*·\s*Featured releases.*Hide this placement/i);
  expect(row().getByRole('button', { name: 'Hide this placement' })).toBeDisabled();
  saved = { ...saved, revision: `cr_${'b'.repeat(43)}`, items: [{ ...saved.items[0], name: 'Renamed after the uncertain hide' }] };
  await act(async () => { await client.refetchQueries({ queryKey: ['admin-imports'] }); });
  expect(screen.getByRole('alert')).toHaveTextContent(/Featured releases.*Hide this placement/i);
  fireEvent.click(screen.getByRole('button', { name: 'Library' }));
  await screen.findByText('This page has no placements.');
  fireEvent.click(screen.getByRole('button', { name: 'Home' }));
  const retry = await screen.findByRole('button', { name: 'Retry original operation' });
  expect(screen.getByRole('alert')).toHaveTextContent(/Featured releases.*Hide this placement/i);
  fireEvent.click(retry);
  await screen.findByRole('button', { name: 'Make this placement public' });
  expect(writes).toHaveLength(2);
  expect(writes[1]).toEqual(writes[0]);
  expect(writes[0]).toMatchObject({ path: '/api/admin/v1/pages/home/items/222222222222222222222222', body: { expectedRevision: revision, visibility: 'hidden', operationId: expect.any(String) } });
});

test('a definite conflict asks for refresh in its alert and never offers original-operation retry', async () => {
  let reads = 0; const writes: unknown[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_path: string, init: RequestInit = {}) => {
    if (init.method === 'PATCH') { writes.push(JSON.parse(String(init.body))); return json({ code: 'ADMIN_PAGE_REVISION_CONFLICT' }, 409); }
    reads++; return json({ page: page() });
  }));
  await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  fireEvent.click(row().getByRole('button', { name: 'Hide this placement' }));
  fireEvent.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Hide this placement' }));
  const alert = await screen.findByRole('alert');
  expect(alert).toHaveTextContent('This page was updated by another operation. Refresh and review it again.');
  expect(screen.queryByRole('button', { name: 'Retry original operation' })).not.toBeInTheDocument();
  const previous = reads;
  fireEvent.click(within(alert).getByRole('button', { name: 'Refresh status' }));
  await waitFor(() => expect(reads).toBeGreaterThan(previous));
  expect(writes).toHaveLength(1);
});

test('administrator suspension removes private placements and prevents fresh Page reads', async () => {
  const fetch = vi.fn(async () => json({ page: page() })); vi.stubGlobal('fetch', fetch);
  await mount();
  await screen.findByRole('heading', { name: '1 · Featured releases' });
  fireEvent.click(row().getByRole('button', { name: 'Details' }));
  expect(screen.getByText('shared-carousel')).toBeVisible();
  const previous = fetch.mock.calls.length;
  act(() => adminWorkspace.suspend());
  expect(screen.queryByRole('heading', { name: '1 · Featured releases' })).not.toBeInTheDocument();
  expect(screen.queryByText('shared-carousel')).not.toBeInTheDocument();
  expect(screen.queryByRole('button', { name: 'Hide this placement' })).not.toBeInTheDocument();
  expect(fetch).toHaveBeenCalledTimes(previous);
});
